def get_flit_core_unmet_exception():
    in_venv = sys.prefix != sys.base_prefix
    with open(BOOTSTRAP_REQUIREMENTS) as f:
        flit_core_req = [l for l in f.read().split('\n') if 'flit_core' in l]
    return UnmetDependenciesException(
        [('flit_core', None, list(parse_requirements(flit_core_req))[0])],
        in_venv,
        reason=(
            'flit_core is needed ahead of time in order to parse the '
            'rest of the requirements.'
        ),
    )

def install_packages(package_dir):
    """Builds setup environment and installs copies of local packages for CLI"""

    if not virtualenv_enabled():
        raise InstallationError(
            "Installation being performed outside of a virtualenv. Please enable before running."
        )
    else:
        pip_install_packages(package_dir)

def _ensure_host_id(self):
    cur = self.execute(self._CHECK_HOST_ID)
    host_id_ct = cur.fetchone()[0]
    if host_id_ct == 0:
        self.execute(
            self._INSERT_HOST_ID,
            # Hardcode `0` as primary key to ensure
            # there's only ever 1 host id in the table.
            (
                0,
                str(uuid.uuid4()),
            ),
        )

def test_no_duplicates(self):
    ies = gen_extractors()
    for tc in gettestcases(include_onlymatching=True):
        url = tc['url']
        for ie in ies:
            if type(ie).__name__ in ('GenericIE', tc['name'] + 'IE'):
                self.assertTrue(ie.suitable(url), '%s should match URL %r' % (type(ie).__name__, url))
            else:
                self.assertFalse(
                    ie.suitable(url),
                    '%s should not match URL %r . That URL belongs to %s.' % (type(ie).__name__, url, tc['name']))

def props_to_json_schema(input_dict, required_fields=None):
    schema: Dict[str, Any] = {"type": "object", "properties": {}, "required": required_fields or []}

    def infer_array_item_type(prop):
        type_map = {
            "string": "string",
            "int": "number",
            "float": "number",
            "dict": "object",
            "list": "array",
            "bool": "boolean",
            "none": "null",
        }
        if prop.get("items", {}).get("type"):
            return prop["items"]["type"]
        if "prefill" in prop and prop["prefill"] and len(prop["prefill"]) > 0:
            return type_map.get(type(prop["prefill"][0]).__name__.lower(), "string")
        if "default" in prop and prop["default"] and len(prop["default"]) > 0:
            return type_map.get(type(prop["default"][0]).__name__.lower(), "string")
        return "string"  # Fallback for arrays like searchStringsArray

    for key, value in input_dict.items():
        prop_schema: Dict[str, Any] = {}
        prop_type = value.get("type")

        if "enum" in value:
            prop_schema["enum"] = value["enum"]

        if "default" in value:
            prop_schema["default"] = value["default"]
        elif "prefill" in value:
            prop_schema["default"] = value["prefill"]

        if "description" in value:
            prop_schema["description"] = value["description"]

        # Handle Apify special types first
        if prop_type == "object" and value.get("editor") == "proxy":
            prop_schema["type"] = "object"
            prop_schema["properties"] = {
                "useApifyProxy": {
                    "title": "Use Apify Proxy",
                    "type": "boolean",
                    "description": "Whether to use Apify Proxy - ALWAYS SET TO TRUE.",
                    "default": True,
                    "examples": [True],
                }
            }
            prop_schema["required"] = ["useApifyProxy"]
            if "default" in value:
                prop_schema["default"] = value["default"]

        elif prop_type == "array" and value.get("editor") == "requestListSources":
            prop_schema["type"] = "array"
            prop_schema["items"] = {
                "type": "object",
                "title": "Request list source",
                "description": "Request list source",
                "properties": {
                    "url": {"title": "URL", "type": "string", "description": "URL of the request list source"}
                },
            }

        elif prop_type == "array":
            prop_schema["type"] = "array"
            prop_schema["items"] = {
                "type": infer_array_item_type(value),
                "title": value.get("title", "Item"),
                "description": "Item",
            }

        elif prop_type == "object":
            prop_schema["type"] = "object"
            if "default" in value:
                prop_schema["default"] = value["default"]
                prop_schema["properties"] = {}
                for k, v in value.get("properties", value["default"]).items():
                    prop_type = v["type"] if isinstance(v, dict) else type(v).__name__.lower()
                    if prop_type == "bool":
                        prop_type = "boolean"
                    prop_schema["properties"][k] = {"type": prop_type}

        else:
            prop_schema["type"] = prop_type

        schema["properties"][key] = prop_schema

    return schema

try:
    from firecrawl import FirecrawlApp, ScrapeOptions  # type: ignore[attr-defined]
except ImportError:
    raise ImportError("`firecrawl-py` not installed. Please install using `pip install firecrawl-py`")

def read(self, file: Union[Path, IO[Any]]) -> List[Document]:
    try:
        if isinstance(file, Path):
            if not file.exists():
                raise FileNotFoundError(f"Could not find file: {file}")
            log_info(f"Reading: {file}")
            file_name = file.stem
            file_contents = file.read_text("utf-8")
        else:
            log_info(f"Reading uploaded file: {file.name}")
            file_name = file.name.split(".")[0]
            file.seek(0)
            file_contents = file.read().decode("utf-8")

        documents = [
            Document(
                name=file_name,
                id=str({uuid.uuid4()}),
                content=file_contents,
            )
        ]
        if self.chunk:
            chunked_documents = []
            for document in documents:
                chunked_documents.extend(self.chunk_document(document))
            return chunked_documents
        return documents
    except Exception as e:
        logger.error(f"Error reading: {file}: {e}")
        return []

async def async_read(self, file: Union[Path, IO[Any]]) -> List[Document]:
    try:
        if isinstance(file, Path):
            if not file.exists():
                raise FileNotFoundError(f"Could not find file: {file}")

            log_info(f"Reading asynchronously: {file}")
            file_name = file.stem

            try:
                import aiofiles

                async with aiofiles.open(file, "r", encoding="utf-8") as f:
                    file_contents = await f.read()
            except ImportError:
                logger.warning("aiofiles not installed, using synchronous file I/O")
                file_contents = file.read_text("utf-8")
        else:
            log_info(f"Reading uploaded file asynchronously: {file.name}")
            file_name = file.name.split(".")[0]
            file.seek(0)
            file_contents = file.read().decode("utf-8")

        document = Document(
            name=file_name,
            id=str({uuid.uuid4()}),
            content=file_contents,
        )

        if self.chunk:
            return await self._async_chunk_document(document)
        return [document]
    except Exception as e:
        logger.error(f"Error reading asynchronously: {file}: {e}")
        return []

