def from_string(cls, s, strict=False):
    m = match(r"^@?local/(.+)$", s)
    if m is None:
        if not strict:
            m = match(r"^(.+?)/(.+?)/(.+?)(?:@(.+?))?$", s)
        else:
            m = match(r"^(.+?)/(.+?)/(.+?)@(.+?)$", s)

    if m is not None:
        return Plugin(*m.groups())
    raise InvalidPluginError("Cannot decipher %s.", s)  # pylint: disable=raising-format-tuple

async def download_plugin(self, plugin, force=False):
    if plugin.abs_path.exists() and (not force or plugin.local):
        return

    if plugin.local:
        raise InvalidPluginError(f"Local plugin {plugin} not found!")

    plugin.abs_path.mkdir(parents=True, exist_ok=True)

    if plugin.cache_path.exists() and not force:
        plugin_io = plugin.cache_path.open("rb")
        logger.debug("Loading cached %s.", plugin.cache_path)
    else:
        headers = {}
        github_token = self.bot.config["github_token"]
        if github_token is not None:
            headers["Authorization"] = f"token {github_token}"

        async with self.bot.session.get(plugin.url, headers=headers) as resp:
            logger.debug("Downloading %s.", plugin.url)
            raw = await resp.read()

            try:
                raw = await resp.text()
            except UnicodeDecodeError:
                pass
            else:
                if raw == "Not Found":
                    raise InvalidPluginError("Plugin not found")
                else:
                    raise InvalidPluginError("Invalid download received, non-bytes object")

        plugin_io = io.BytesIO(raw)
        if not plugin.cache_path.parent.exists():
            plugin.cache_path.parent.mkdir(parents=True)

        with plugin.cache_path.open("wb") as f:
            f.write(raw)

    with zipfile.ZipFile(plugin_io) as zipf:
        for info in zipf.infolist():
            path = PurePath(info.filename)
            if len(path.parts) >= 3 and path.parts[1] == plugin.name:
                plugin_path = plugin.abs_path / Path(*path.parts[2:])
                if info.is_dir():
                    plugin_path.mkdir(parents=True, exist_ok=True)
                else:
                    plugin_path.parent.mkdir(parents=True, exist_ok=True)
                    with zipf.open(info) as src, plugin_path.open("wb") as dst:
                        shutil.copyfileobj(src, dst)

    plugin_io.close()

async def plugins_reset(self, ctx):
    """
    Reset all plugins for the bot.

    Deletes all cache and plugins from config and unloads from the bot.
    """
    logger.warning("Purging plugins.")
    for ext in list(self.bot.extensions):
        if not ext.startswith("plugins."):
            continue
        logger.error("Unloading plugin: %s.", ext)
        try:
            plugin = next((p for p in self.loaded_plugins if p.ext_string == ext), None)
            if plugin:
                await self.unload_plugin(plugin)
                self.loaded_plugins.remove(plugin)
            else:
                await self.bot.unload_extension(ext)
        except Exception:
            logger.error("Failed to unload plugin: %s.", ext)

    for module in list(sys.modules.keys()):
        if module.startswith("plugins."):
            del sys.modules[module]

    self.bot.config["plugins"].clear()
    await self.bot.config.update()

    cache_path = Path(__file__).absolute().parent.parent / "temp" / "plugins-cache"
    if cache_path.exists():
        logger.warning("Removing cache path.")
        shutil.rmtree(cache_path)

    for entry in os.scandir(Path(__file__).absolute().parent.parent / "plugins"):
        if entry.is_dir() and entry.name != "@local":
            shutil.rmtree(entry.path)
            logger.warning("Removing %s.", entry.name)

    embed = discord.Embed(
        description="Successfully purged all plugins from the bot.", color=self.bot.main_color
    )
    return await ctx.send(embed=embed)

async def _close(self, closer, silent=False, delete_channel=True, message=None, scheduled=False):
    if self.channel:
        self.manager.closing.add(self.channel.id)
    try:
        self.manager.cache.pop(self.id)
    except KeyError as e:
        logger.error("Thread already closed: %s.", e)
        return

    await self.cancel_closure(all=True)

    # Cancel auto closing the thread if closed by any means.

    self.bot.config["subscriptions"].pop(str(self.id), None)
    self.bot.config["notification_squad"].pop(str(self.id), None)

    # Logging
    if self.channel:
        log_data = await self.bot.api.post_log(
            self.channel.id,
            {
                "open": False,
                "title": match_title(self.channel.topic),
                "closed_at": str(discord.utils.utcnow()),
                "nsfw": self.channel.nsfw,
                "close_message": message,
                "closer": {
                    "id": str(closer.id),
                    "name": closer.name,
                    "discriminator": closer.discriminator,
                    "avatar_url": closer.display_avatar.url,
                    "mod": True,
                },
            },
        )
    else:
        log_data = None

    if isinstance(log_data, dict):
        prefix = self.bot.config["log_url_prefix"].strip("/")
        if prefix == "NONE":
            prefix = ""
        log_url = (
            f"{self.bot.config['log_url'].strip('/')}{'/' + prefix if prefix else ''}/{log_data['key']}"
        )

        if log_data["title"]:
            sneak_peak = log_data["title"]
        elif log_data["messages"]:
            content = str(log_data["messages"][0]["content"])
            sneak_peak = content.replace("\n", "")
        else:
            sneak_peak = "No content"

        if self.channel.nsfw:
            _nsfw = "NSFW-"
        else:
            _nsfw = ""

        desc = f"[`{_nsfw}{log_data['key']}`]({log_url}): "
        desc += truncate(sneak_peak, max=75 - 13)
    else:
        desc = "Could not resolve log url."
        log_url = None

    embed = discord.Embed(description=desc, color=self.bot.error_color)

    if self.recipient is not None:
        user = f"{self.recipient} (`{self.id}`)"
    else:
        user = f"`{self.id}`"

    if self.id == closer.id:
        _closer = "the Recipient"
    else:
        _closer = f"{closer} ({closer.id})"

    embed.title = user

    event = "Thread Closed as Scheduled" if scheduled else "Thread Closed"
    # embed.set_author(name=f"Event: {event}", url=log_url)
    embed.set_footer(text=f"{event} by {_closer}", icon_url=closer.display_avatar.url)
    embed.timestamp = discord.utils.utcnow()

    tasks = [self.bot.config.update()]

    if self.bot.log_channel is not None and self.channel is not None:
        if self.bot.config["show_log_url_button"]:
            view = discord.ui.View()
            view.add_item(discord.ui.Button(label="Log link", url=log_url, style=discord.ButtonStyle.url))
        else:
            view = None
        tasks.append(self.bot.log_channel.send(embed=embed, view=view))

    # Thread closed message

    embed = discord.Embed(
        title=self.bot.config["thread_close_title"],
        color=self.bot.error_color,
    )
    if self.bot.config["show_timestamp"]:
        embed.timestamp = discord.utils.utcnow()

    if not message:
        if self.id == closer.id:
            message = self.bot.config["thread_self_close_response"]
        else:
            message = self.bot.config["thread_close_response"]

    message = self.bot.formatter.format(
        message, closer=closer, loglink=log_url, logkey=log_data["key"] if log_data else None
    )

    embed.description = message
    footer = self.bot.config["thread_close_footer"]
    embed.set_footer(text=footer, icon_url=self.bot.get_guild_icon(guild=self.bot.guild, size=128))

    if not silent:
        for user in self.recipients:
            if not message:
                if user.id == closer.id:
                    message = self.bot.config["thread_self_close_response"]
                else:
                    message = self.bot.config["thread_close_response"]
                embed.description = message

            if user is not None:
                tasks.append(user.send(embed=embed))

    if delete_channel and self.channel:
        tasks.append(self.channel.delete())

    try:
        await asyncio.gather(*tasks)
    finally:
        if self.channel:
            self.manager.closing.discard(self.channel.id)

    self.bot.dispatch("thread_close", self, closer, silent, delete_channel, message, scheduled)

async def cancel_closure(self, auto_close: bool = False, all: bool = False) -> None:
    if self.close_task is not None and (not auto_close or all):
        self.close_task.cancel()
        self.close_task = None
    if self.auto_close_task is not None and (auto_close or all):
        self.auto_close_task.cancel()
        self.auto_close_task = None

    to_update = self.bot.config["closures"].pop(str(self.id), None)
    if to_update is not None:
        await self.bot.config.update()

