async def _close(self, closer, silent=False, delete_channel=True, message=None, scheduled=False):
    if self.channel:
        self.manager.closing.add(self.channel.id)
    try:
        self.manager.cache.pop(self.id)
    except KeyError as e:
        logger.error("Thread already closed: %s.", e)
        return

    await self.cancel_closure(all=True)

    # Cancel auto closing the thread if closed by any means.

    self.bot.config["subscriptions"].pop(str(self.id), None)
    self.bot.config["notification_squad"].pop(str(self.id), None)

    # Logging
    if self.channel:
        log_data = await self.bot.api.post_log(
            self.channel.id,
            {
                "open": False,
                "title": match_title(self.channel.topic),
                "closed_at": str(discord.utils.utcnow()),
                "nsfw": self.channel.nsfw,
                "close_message": message,
                "closer": {
                    "id": str(closer.id),
                    "name": closer.name,
                    "discriminator": closer.discriminator,
                    "avatar_url": closer.display_avatar.url,
                    "mod": True,
                },
            },
        )
    else:
        log_data = None

    if isinstance(log_data, dict):
        prefix = self.bot.config["log_url_prefix"].strip("/")
        if prefix == "NONE":
            prefix = ""
        log_url = (
            f"{self.bot.config['log_url'].strip('/')}{'/' + prefix if prefix else ''}/{log_data['key']}"
        )

        if log_data["title"]:
            sneak_peak = log_data["title"]
        elif log_data["messages"]:
            content = str(log_data["messages"][0]["content"])
            sneak_peak = content.replace("\n", "")
        else:
            sneak_peak = "No content"

        if self.channel.nsfw:
            _nsfw = "NSFW-"
        else:
            _nsfw = ""

        desc = f"[`{_nsfw}{log_data['key']}`]({log_url}): "
        desc += truncate(sneak_peak, max=75 - 13)
    else:
        desc = "Could not resolve log url."
        log_url = None

    embed = discord.Embed(description=desc, color=self.bot.error_color)

    if self.recipient is not None:
        user = f"{self.recipient} (`{self.id}`)"
    else:
        user = f"`{self.id}`"

    if self.id == closer.id:
        _closer = "the Recipient"
    else:
        _closer = f"{closer} ({closer.id})"

    embed.title = user

    event = "Thread Closed as Scheduled" if scheduled else "Thread Closed"
    # embed.set_author(name=f"Event: {event}", url=log_url)
    embed.set_footer(text=f"{event} by {_closer}", icon_url=closer.display_avatar.url)
    embed.timestamp = discord.utils.utcnow()

    tasks = [self.bot.config.update()]

    if self.bot.log_channel is not None and self.channel is not None:
        if self.bot.config["show_log_url_button"]:
            view = discord.ui.View()
            view.add_item(discord.ui.Button(label="Log link", url=log_url, style=discord.ButtonStyle.url))
        else:
            view = None
        tasks.append(self.bot.log_channel.send(embed=embed, view=view))

    # Thread closed message

    embed = discord.Embed(
        title=self.bot.config["thread_close_title"],
        color=self.bot.error_color,
    )
    if self.bot.config["show_timestamp"]:
        embed.timestamp = discord.utils.utcnow()

    if not message:
        if self.id == closer.id:
            message = self.bot.config["thread_self_close_response"]
        else:
            message = self.bot.config["thread_close_response"]

    message = self.bot.formatter.format(
        message, closer=closer, loglink=log_url, logkey=log_data["key"] if log_data else None
    )

    embed.description = message
    footer = self.bot.config["thread_close_footer"]
    embed.set_footer(text=footer, icon_url=self.bot.get_guild_icon(guild=self.bot.guild, size=128))

    if not silent:
        for user in self.recipients:
            if not message:
                if user.id == closer.id:
                    message = self.bot.config["thread_self_close_response"]
                else:
                    message = self.bot.config["thread_close_response"]
                embed.description = message

            if user is not None:
                tasks.append(user.send(embed=embed))

    if delete_channel and self.channel:
        tasks.append(self.channel.delete())

    try:
        await asyncio.gather(*tasks)
    finally:
        if self.channel:
            self.manager.closing.discard(self.channel.id)

    self.bot.dispatch("thread_close", self, closer, silent, delete_channel, message, scheduled)

async def cancel_closure(self, auto_close: bool = False, all: bool = False) -> None:
    if self.close_task is not None and (not auto_close or all):
        self.close_task.cancel()
        self.close_task = None
    if self.auto_close_task is not None and (auto_close or all):
        self.auto_close_task.cancel()
        self.auto_close_task = None

    to_update = self.bot.config["closures"].pop(str(self.id), None)
    if to_update is not None:
        await self.bot.config.update()

async def find_linked_messages(
    self,
    message_id: typing.Optional[int] = None,
    either_direction: bool = False,
    message1: discord.Message = None,
    note: bool = True,
) -> typing.Tuple[discord.Message, typing.List[typing.Optional[discord.Message]]]:
    if message1 is not None:
        if not message1.embeds or not message1.embeds[0].author.url or message1.author != self.bot.user:
            raise ValueError("Malformed thread message.")

    elif message_id is not None:
        try:
            message1 = await self.channel.fetch_message(message_id)
        except discord.NotFound:
            raise ValueError("Thread message not found.")

        if not (
            message1.embeds
            and message1.embeds[0].author.url
            and message1.embeds[0].color
            and message1.author == self.bot.user
        ):
            raise ValueError("Thread message not found.")

        if message1.embeds[0].footer and "Internal Message" in message1.embeds[0].footer.text:
            if not note:
                raise ValueError("Thread message not found.")
            return message1, None

        if message1.embeds[0].color.value != self.bot.mod_color and not (
            either_direction and message1.embeds[0].color.value == self.bot.recipient_color
        ):
            raise ValueError("Thread message not found.")
    else:
        async for message1 in self.channel.history():
            if (
                message1.embeds
                and message1.embeds[0].author.url
                and message1.embeds[0].color
                and (
                    message1.embeds[0].color.value == self.bot.mod_color
                    or (either_direction and message1.embeds[0].color.value == self.bot.recipient_color)
                )
                and message1.embeds[0].author.url.split("#")[-1].isdigit()
                and message1.author == self.bot.user
            ):
                break
        else:
            raise ValueError("Thread message not found.")

    try:
        joint_id = int(message1.embeds[0].author.url.split("#")[-1])
    except ValueError:
        raise ValueError("Malformed thread message.")

    messages = [message1]
    for user in self.recipients:
        async for msg in user.history():
            if either_direction:
                if msg.id == joint_id:
                    return message1, msg

            if not (msg.embeds and msg.embeds[0].author.url):
                continue
            try:
                if int(msg.embeds[0].author.url.split("#")[-1]) == joint_id:
                    messages.append(msg)
                    break
            except ValueError:
                continue

    if len(messages) > 1:
        return messages

    raise ValueError("DM message not found.")

async def edit_message(self, message_id: typing.Optional[int], message: str) -> None:
    try:
        message1, *message2 = await self.find_linked_messages(message_id)
    except ValueError:
        logger.warning("Failed to edit message.", exc_info=True)
        raise

    embed1 = message1.embeds[0]
    embed1.description = message

    tasks = [self.bot.api.edit_message(message1.id, message), message1.edit(embed=embed1)]
    if message1.embeds[0].footer and "Persistent Internal Message" in message1.embeds[0].footer.text:
        tasks += [self.bot.api.edit_note(message1.id, message)]
    else:
        for m2 in message2:
            if m2 is not None:
                embed2 = m2.embeds[0]
                embed2.description = message
                tasks += [m2.edit(embed=embed2)]

    await asyncio.gather(*tasks)

async def delete_message(
    self, message: typing.Union[int, discord.Message] = None, note: bool = True
) -> None:
    if isinstance(message, discord.Message):
        message1, *message2 = await self.find_linked_messages(message1=message, note=note)
    else:
        message1, *message2 = await self.find_linked_messages(message, note=note)
    tasks = []

    if not isinstance(message, discord.Message):
        tasks += [message1.delete()]

    for m2 in message2:
        if m2 is not None:
            tasks += [m2.delete()]

    if message1.embeds[0].footer and "Persistent Internal Message" in message1.embeds[0].footer.text:
        tasks += [self.bot.api.delete_note(message1.id)]

    if tasks:
        await asyncio.gather(*tasks)

async def reply(
    self, message: discord.Message, anonymous: bool = False, plain: bool = False
) -> typing.Tuple[typing.List[discord.Message], discord.Message]:
    """Returns List[user_dm_msg] and thread_channel_msg"""
    if not message.content and not message.attachments and not message.stickers:
        raise MissingRequiredArgument(DummyParam("msg"))
    for guild in self.bot.guilds:
        try:
            if await self.bot.get_or_fetch_member(guild, self.id):
                break
        except discord.NotFound:
            pass
    else:
        return await message.channel.send(
            embed=discord.Embed(
                color=self.bot.error_color,
                description="Your message could not be delivered since "
                "the recipient shares no servers with the bot.",
            )
        )

    user_msg_tasks = []
    tasks = []

    for user in self.recipients:
        user_msg_tasks.append(
            self.send(
                message,
                destination=user,
                from_mod=True,
                anonymous=anonymous,
                plain=plain,
            )
        )

    try:
        user_msg = await asyncio.gather(*user_msg_tasks)
    except Exception as e:
        logger.error("Message delivery failed:", exc_info=True)
        user_msg = None
        if isinstance(e, discord.Forbidden):
            description = (
                "Your message could not be delivered as "
                "the recipient is only accepting direct "
                "messages from friends, or the bot was "
                "blocked by the recipient."
            )
        else:
            description = (
                "Your message could not be delivered due "
                "to an unknown error. Check `?debug` for "
                "more information"
            )
        msg = await message.channel.send(
            embed=discord.Embed(
                color=self.bot.error_color,
                description=description,
            )
        )
    else:
        # Send the same thing in the thread channel.
        msg = await self.send(
            message, destination=self.channel, from_mod=True, anonymous=anonymous, plain=plain
        )

        tasks.append(
            self.bot.api.append_log(
                message,
                message_id=msg.id,
                channel_id=self.channel.id,
                type_="anonymous" if anonymous else "thread_message",
            )
        )

        # Cancel closing if a thread message is sent.
        if self.close_task is not None:
            await self.cancel_closure()
            tasks.append(
                self.channel.send(
                    embed=discord.Embed(
                        color=self.bot.error_color,
                        description="Scheduled close has been cancelled.",
                    )
                )
            )

    await asyncio.gather(*tasks)
    self.bot.dispatch("thread_reply", self, True, message, anonymous, plain)
    return (user_msg, msg)  # sent_to_user, sent_to_thread_channel

async def send(
    self,
    message: discord.Message,
    destination: typing.Union[
        discord.TextChannel, discord.DMChannel, discord.User, discord.Member
    ] = None,
    from_mod: bool = False,
    note: bool = False,
    anonymous: bool = False,
    plain: bool = False,
    persistent_note: bool = False,
    thread_creation: bool = False,
) -> None:
    if not note and from_mod:
        self.bot.loop.create_task(self._restart_close_timer())  # Start or restart thread auto close

    if self.close_task is not None:
        # cancel closing if a thread message is sent.
        self.bot.loop.create_task(self.cancel_closure())
        self.bot.loop.create_task(
            self.channel.send(
                embed=discord.Embed(
                    color=self.bot.error_color,
                    description="Scheduled close has been cancelled.",
                )
            )
        )

    if not self.ready:
        await self.wait_until_ready()

    if not from_mod and not note:
        self.bot.loop.create_task(self.bot.api.append_log(message, channel_id=self.channel.id))

    destination = destination or self.channel

    if destination is None:
        logger.error("Attempted to send a message to a thread with no channel (destination is None).")
        return
    try:
        await destination.typing()
    except discord.NotFound:
        logger.warning("Channel not found when trying to send message.")
        return

    author = message.author
    member = self.bot.guild.get_member(author.id)
    if member:
        avatar_url = member.display_avatar.url
    else:
        avatar_url = author.display_avatar.url

    #  Extract content for blank/forwarded messages ---
    content = message.content
    if not content:
        # Try to extract from referenced message (replies)
        if hasattr(message, "reference") and message.reference is not None:
            try:
                ref = message.reference.resolved
                if ref and hasattr(ref, "content") and ref.content:
                    content = f"(Reply to: {ref.author}: {ref.content})"
            except Exception:
                pass
        # Try to extract from first embed's description
        if not content and message.embeds:
            first_embed = message.embeds[0]
            if hasattr(first_embed, "description") and first_embed.description:
                content = first_embed.description
        # Fallback: show something generic if still blank
        if not content:
            content = "[This is a forwarded message.]"

    embed = discord.Embed(description=content)
    if self.bot.config["show_timestamp"]:
        embed.timestamp = message.created_at

    system_avatar_url = "https://discordapp.com/assets/f78426a064bc9dd24847519259bc42af.png"

    if not note:
        if anonymous and from_mod and not isinstance(destination, discord.TextChannel):
            # Anonymously sending to the user.
            tag = self.bot.config["mod_tag"]
            if tag is None:
                tag = str(get_top_role(author, self.bot.config["use_hoisted_top_role"]))
            name = self.bot.config["anon_username"]
            if name is None:
                name = tag
            avatar_url = self.bot.config["anon_avatar_url"]
            if avatar_url is None:
                avatar_url = self.bot.get_guild_icon(guild=self.bot.guild, size=128)
            embed.set_author(
                name=name,
                icon_url=avatar_url,
                url=f"https://discordapp.com/channels/{self.bot.guild.id}#{message.id}",
            )
        else:
            # Normal message
            name = str(author)
            avatar_url = avatar_url
            embed.set_author(
                name=name,
                icon_url=avatar_url,
                url=f"https://discordapp.com/users/{author.id}#{message.id}",
            )
    else:
        # Notes are just replies with a different footer and color
        embed.set_author(
            name=str(author),
            icon_url=avatar_url,
            url=f"https://discordapp.com/users/{author.id}#{message.id}",
        )

    ext = [(a.url, a.filename, False) for a in message.attachments]

    images = []
    attachments = []
    for attachment in ext:
        if is_image_url(attachment[0]):
            images.append(attachment)
        else:
            attachments.append(attachment)

    image_urls = re.findall(
        r"http[s]?:\/\/(?:[a-zA-Z]|[0-9]|[$-_@.&+]|[!*(),]|(?:%[0-9a-fA-F][0-9a-fA-F]))+",
        message.content,
    )

    image_urls = [
        (is_image_url(url, convert_size=False), None, False)
        for url in image_urls
        if is_image_url(url, convert_size=False)
    ]
    images.extend(image_urls)

    def lottie_to_png(data):
        importer = l_importers.get("lottie")
        exporter = l_exporters.get("png")
        with io.BytesIO() as stream:
            stream.write(data)
            stream.seek(0)
            an = importer.process(stream)

        with io.BytesIO() as stream:
            exporter.process(an, stream)
            stream.seek(0)
            return stream.read()

    for i in message.stickers:
        if i.format in (
            discord.StickerFormatType.png,
            discord.StickerFormatType.apng,
            discord.StickerFormatType.gif,
        ):
            images.append(
                (f"https://media.discordapp.net/stickers/{i.id}.{i.format.file_extension}", i.name, True)
            )
        elif i.format == discord.StickerFormatType.lottie:
            # save the json lottie representation
            try:
                async with self.bot.session.get(i.url) as resp:
                    data = await resp.read()

                # convert to a png
                img_data = await self.bot.loop.run_in_executor(
                    None, functools.partial(lottie_to_png, data)
                )
                b64_data = base64.b64encode(img_data).decode()

                # upload to imgur
                async with self.bot.session.post(
                    "https://api.imgur.com/3/image",
                    headers={"Authorization": "Client-ID 50e96145ac5e085"},
                    data={"image": b64_data},
                ) as resp:
                    result = await resp.json()
                    url = result["data"]["link"]

            except Exception:
                traceback.print_exc()
                images.append((None, i.name, True))
            else:
                images.append((url, i.name, True))
        else:
            images.append((None, i.name, True))

    embedded_image = False

    prioritize_uploads = any(i[1] is not None for i in images)

    additional_images = []
    additional_count = 1

    for url, filename, is_sticker in images:
        if (
            not prioritize_uploads or ((url is None or is_image_url(url)) and filename)
        ) and not embedded_image:
            if url is not None:
                embed.set_image(url=url)
            if filename:
                if is_sticker:
                    if url is None:
                        description = f"{filename}: Unable to retrieve sticker image"
                    else:
                        description = f"[{filename}]({url})"
                    embed.add_field(name="Sticker", value=description)
                else:
                    embed.add_field(name="Image", value=f"[{filename}]({url})")
            embedded_image = True
        else:
            if note:
                color = self.bot.main_color
            elif from_mod:
                color = self.bot.mod_color
            else:
                color = self.bot.recipient_color

            img_embed = discord.Embed(color=color)

            if url is not None:
                img_embed.set_image(url=url)
                img_embed.url = url
            if filename is not None:
                img_embed.title = filename
            img_embed.set_footer(text=f"Additional Image Upload ({additional_count})")
            img_embed.timestamp = message.created_at
            additional_images.append(destination.send(embed=img_embed))
            additional_count += 1

    file_upload_count = 1

    for url, filename, _ in attachments:
        embed.add_field(name=f"File upload ({file_upload_count})", value=f"[{filename}]({url})")
        file_upload_count += 1

    if from_mod:
        embed.colour = self.bot.mod_color
        if note:
            embed.set_footer(text=f"{'Persistent' if persistent_note else ''} Internal Message")
        # Anonymous reply sent in thread channel
        elif anonymous and isinstance(destination, discord.TextChannel):
            embed.set_footer(text="Anonymous Reply")
        # Normal messages
        elif not anonymous:
            mod_tag = self.bot.config["mod_tag"]
            if mod_tag is None:
                mod_tag = str(get_top_role(message.author, self.bot.config["use_hoisted_top_role"]))
            embed.set_footer(text=mod_tag)  # Normal messages
        else:
            embed.set_footer(text=self.bot.config["anon_tag"])
    else:
        embed.set_footer(text=f"Message ID: {message.id}")
        embed.colour = self.bot.recipient_color

    if (from_mod or note) and not thread_creation:
        delete_message = not bool(message.attachments)
        if delete_message and destination == self.channel:
            try:
                await message.delete()
            except Exception as e:
                logger.warning("Cannot delete message: %s.", e)

    if (
        from_mod
        and self.bot.config["dm_disabled"] == DMDisabled.ALL_THREADS
        and destination != self.channel
    ):
        logger.info("Sending a message to %s when DM disabled is set.", self.recipient)

    try:
        await destination.typing()
    except discord.NotFound:
        logger.warning("Channel not found.")
        raise

    if not from_mod and not note:
        mentions = await self.get_notifications()
    else:
        mentions = None

    if plain:
        if from_mod and not isinstance(destination, discord.TextChannel):
            # Plain to user
            with warnings.catch_warnings():
                # Catch coroutines not awaited warning
                warnings.simplefilter("ignore")
                additional_images = []

            if embed.footer.text:
                plain_message = f"**{embed.footer.text} "
            else:
                plain_message = "**"
            plain_message += f"{embed.author.name}:** {embed.description}"
            files = []
            for i in message.attachments:
                files.append(await i.to_file())

            msg = await destination.send(plain_message, files=files)
        else:
            # Plain to mods
            embed.set_footer(text="[PLAIN] " + embed.footer.text)
            msg = await destination.send(mentions, embed=embed)

    else:
        msg = await destination.send(mentions, embed=embed)

    if additional_images:
        self.ready = False
        await asyncio.gather(*additional_images)
        self.ready = True

    return msg

async def _close(self, closer, silent=False, delete_channel=True, message=None, scheduled=False):
    if self.channel:
        self.manager.closing.add(self.channel.id)
    try:
        self.manager.cache.pop(self.id)
    except KeyError as e:
        logger.error("Thread already closed: %s.", e)
        return

    await self.cancel_closure(all=True)

    # Cancel auto closing the thread if closed by any means.

    self.bot.config["subscriptions"].pop(str(self.id), None)
    self.bot.config["notification_squad"].pop(str(self.id), None)

    # Logging
    if self.channel:
        log_data = await self.bot.api.post_log(
            self.channel.id,
            {
                "open": False,
                "title": match_title(self.channel.topic),
                "closed_at": str(discord.utils.utcnow()),
                "nsfw": self.channel.nsfw,
                "close_message": message,
                "closer": {
                    "id": str(closer.id),
                    "name": closer.name,
                    "discriminator": closer.discriminator,
                    "avatar_url": closer.display_avatar.url,
                    "mod": True,
                },
            },
        )
    else:
        log_data = None

    if isinstance(log_data, dict):
        prefix = self.bot.config["log_url_prefix"].strip("/")
        if prefix == "NONE":
            prefix = ""
        log_url = (
            f"{self.bot.config['log_url'].strip('/')}{'/' + prefix if prefix else ''}/{log_data['key']}"
        )

        if log_data["title"]:
            sneak_peak = log_data["title"]
        elif log_data["messages"]:
            content = str(log_data["messages"][0]["content"])
            sneak_peak = content.replace("\n", "")
        else:
            sneak_peak = "No content"

        if self.channel.nsfw:
            _nsfw = "NSFW-"
        else:
            _nsfw = ""

        desc = f"[`{_nsfw}{log_data['key']}`]({log_url}): "
        desc += truncate(sneak_peak, max=75 - 13)
    else:
        desc = "Could not resolve log url."
        log_url = None

    embed = discord.Embed(description=desc, color=self.bot.error_color)

    if self.recipient is not None:
        user = f"{self.recipient} (`{self.id}`)"
    else:
        user = f"`{self.id}`"

    if self.id == closer.id:
        _closer = "the Recipient"
    else:
        _closer = f"{closer} ({closer.id})"

    embed.title = user

    event = "Thread Closed as Scheduled" if scheduled else "Thread Closed"
    # embed.set_author(name=f"Event: {event}", url=log_url)
    embed.set_footer(text=f"{event} by {_closer}", icon_url=closer.display_avatar.url)
    embed.timestamp = discord.utils.utcnow()

    tasks = [self.bot.config.update()]

    if self.bot.log_channel is not None and self.channel is not None:
        if self.bot.config["show_log_url_button"]:
            view = discord.ui.View()
            view.add_item(discord.ui.Button(label="Log link", url=log_url, style=discord.ButtonStyle.url))
        else:
            view = None
        tasks.append(self.bot.log_channel.send(embed=embed, view=view))

    # Thread closed message

    embed = discord.Embed(
        title=self.bot.config["thread_close_title"],
        color=self.bot.error_color,
    )
    if self.bot.config["show_timestamp"]:
        embed.timestamp = discord.utils.utcnow()

    if not message:
        if self.id == closer.id:
            message = self.bot.config["thread_self_close_response"]
        else:
            message = self.bot.config["thread_close_response"]

    message = self.bot.formatter.format(
        message, closer=closer, loglink=log_url, logkey=log_data["key"] if log_data else None
    )

    embed.description = message
    footer = self.bot.config["thread_close_footer"]
    embed.set_footer(text=footer, icon_url=self.bot.get_guild_icon(guild=self.bot.guild, size=128))

    if not silent:
        for user in self.recipients:
            if not message:
                if user.id == closer.id:
                    message = self.bot.config["thread_self_close_response"]
                else:
                    message = self.bot.config["thread_close_response"]
                embed.description = message

            if user is not None:
                tasks.append(user.send(embed=embed))

    if delete_channel and self.channel:
        tasks.append(self.channel.delete())

    try:
        await asyncio.gather(*tasks)
    finally:
        if self.channel:
            self.manager.closing.discard(self.channel.id)

    self.bot.dispatch("thread_close", self, closer, silent, delete_channel, message, scheduled)

async def cancel_closure(self, auto_close: bool = False, all: bool = False) -> None:
    if self.close_task is not None and (not auto_close or all):
        self.close_task.cancel()
        self.close_task = None
    if self.auto_close_task is not None and (auto_close or all):
        self.auto_close_task.cancel()
        self.auto_close_task = None

    to_update = self.bot.config["closures"].pop(str(self.id), None)
    if to_update is not None:
        await self.bot.config.update()

async def find_linked_messages(
    self,
    message_id: typing.Optional[int] = None,
    either_direction: bool = False,
    message1: discord.Message = None,
    note: bool = True,
) -> typing.Tuple[discord.Message, typing.List[typing.Optional[discord.Message]]]:
    if message1 is not None:
        if not message1.embeds or not message1.embeds[0].author.url or message1.author != self.bot.user:
            raise ValueError("Malformed thread message.")

    elif message_id is not None:
        try:
            message1 = await self.channel.fetch_message(message_id)
        except discord.NotFound:
            raise ValueError("Thread message not found.")

        if not (
            message1.embeds
            and message1.embeds[0].author.url
            and message1.embeds[0].color
            and message1.author == self.bot.user
        ):
            raise ValueError("Thread message not found.")

        if message1.embeds[0].footer and "Internal Message" in message1.embeds[0].footer.text:
            if not note:
                raise ValueError("Thread message not found.")
            return message1, None

        if message1.embeds[0].color.value != self.bot.mod_color and not (
            either_direction and message1.embeds[0].color.value == self.bot.recipient_color
        ):
            raise ValueError("Thread message not found.")
    else:
        async for message1 in self.channel.history():
            if (
                message1.embeds
                and message1.embeds[0].author.url
                and message1.embeds[0].color
                and (
                    message1.embeds[0].color.value == self.bot.mod_color
                    or (either_direction and message1.embeds[0].color.value == self.bot.recipient_color)
                )
                and message1.embeds[0].author.url.split("#")[-1].isdigit()
                and message1.author == self.bot.user
            ):
                break
        else:
            raise ValueError("Thread message not found.")

    try:
        joint_id = int(message1.embeds[0].author.url.split("#")[-1])
    except ValueError:
        raise ValueError("Malformed thread message.")

    messages = [message1]
    for user in self.recipients:
        async for msg in user.history():
            if either_direction:
                if msg.id == joint_id:
                    return message1, msg

            if not (msg.embeds and msg.embeds[0].author.url):
                continue
            try:
                if int(msg.embeds[0].author.url.split("#")[-1]) == joint_id:
                    messages.append(msg)
                    break
            except ValueError:
                continue

    if len(messages) > 1:
        return messages

    raise ValueError("DM message not found.")

async def edit_message(self, message_id: typing.Optional[int], message: str) -> None:
    try:
        message1, *message2 = await self.find_linked_messages(message_id)
    except ValueError:
        logger.warning("Failed to edit message.", exc_info=True)
        raise

    embed1 = message1.embeds[0]
    embed1.description = message

    tasks = [self.bot.api.edit_message(message1.id, message), message1.edit(embed=embed1)]
    if message1.embeds[0].footer and "Persistent Internal Message" in message1.embeds[0].footer.text:
        tasks += [self.bot.api.edit_note(message1.id, message)]
    else:
        for m2 in message2:
            if m2 is not None:
                embed2 = m2.embeds[0]
                embed2.description = message
                tasks += [m2.edit(embed=embed2)]

    await asyncio.gather(*tasks)

async def delete_message(
    self, message: typing.Union[int, discord.Message] = None, note: bool = True
) -> None:
    if isinstance(message, discord.Message):
        message1, *message2 = await self.find_linked_messages(message1=message, note=note)
    else:
        message1, *message2 = await self.find_linked_messages(message, note=note)
    tasks = []

    if not isinstance(message, discord.Message):
        tasks += [message1.delete()]

    for m2 in message2:
        if m2 is not None:
            tasks += [m2.delete()]

    if message1.embeds[0].footer and "Persistent Internal Message" in message1.embeds[0].footer.text:
        tasks += [self.bot.api.delete_note(message1.id)]

    if tasks:
        await asyncio.gather(*tasks)

async def reply(
    self, message: discord.Message, anonymous: bool = False, plain: bool = False
) -> typing.Tuple[typing.List[discord.Message], discord.Message]:
    """Returns List[user_dm_msg] and thread_channel_msg"""
    if not message.content and not message.attachments and not message.stickers:
        raise MissingRequiredArgument(DummyParam("msg"))
    for guild in self.bot.guilds:
        try:
            if await self.bot.get_or_fetch_member(guild, self.id):
                break
        except discord.NotFound:
            pass
    else:
        return await message.channel.send(
            embed=discord.Embed(
                color=self.bot.error_color,
                description="Your message could not be delivered since "
                "the recipient shares no servers with the bot.",
            )
        )

    user_msg_tasks = []
    tasks = []

    for user in self.recipients:
        user_msg_tasks.append(
            self.send(
                message,
                destination=user,
                from_mod=True,
                anonymous=anonymous,
                plain=plain,
            )
        )

    try:
        user_msg = await asyncio.gather(*user_msg_tasks)
    except Exception as e:
        logger.error("Message delivery failed:", exc_info=True)
        user_msg = None
        if isinstance(e, discord.Forbidden):
            description = (
                "Your message could not be delivered as "
                "the recipient is only accepting direct "
                "messages from friends, or the bot was "
                "blocked by the recipient."
            )
        else:
            description = (
                "Your message could not be delivered due "
                "to an unknown error. Check `?debug` for "
                "more information"
            )
        msg = await message.channel.send(
            embed=discord.Embed(
                color=self.bot.error_color,
                description=description,
            )
        )
    else:
        # Send the same thing in the thread channel.
        msg = await self.send(
            message, destination=self.channel, from_mod=True, anonymous=anonymous, plain=plain
        )

        tasks.append(
            self.bot.api.append_log(
                message,
                message_id=msg.id,
                channel_id=self.channel.id,
                type_="anonymous" if anonymous else "thread_message",
            )
        )

        # Cancel closing if a thread message is sent.
        if self.close_task is not None:
            await self.cancel_closure()
            tasks.append(
                self.channel.send(
                    embed=discord.Embed(
                        color=self.bot.error_color,
                        description="Scheduled close has been cancelled.",
                    )
                )
            )

    await asyncio.gather(*tasks)
    self.bot.dispatch("thread_reply", self, True, message, anonymous, plain)
    return (user_msg, msg)  # sent_to_user, sent_to_thread_channel

async def send(
    self,
    message: discord.Message,
    destination: typing.Union[
        discord.TextChannel, discord.DMChannel, discord.User, discord.Member
    ] = None,
    from_mod: bool = False,
    note: bool = False,
    anonymous: bool = False,
    plain: bool = False,
    persistent_note: bool = False,
    thread_creation: bool = False,
) -> None:
    if not note and from_mod:
        self.bot.loop.create_task(self._restart_close_timer())  # Start or restart thread auto close

    if self.close_task is not None:
        # cancel closing if a thread message is sent.
        self.bot.loop.create_task(self.cancel_closure())
        self.bot.loop.create_task(
            self.channel.send(
                embed=discord.Embed(
                    color=self.bot.error_color,
                    description="Scheduled close has been cancelled.",
                )
            )
        )

    if not self.ready:
        await self.wait_until_ready()

    if not from_mod and not note:
        self.bot.loop.create_task(self.bot.api.append_log(message, channel_id=self.channel.id))

    destination = destination or self.channel

    if destination is None:
        logger.error("Attempted to send a message to a thread with no channel (destination is None).")
        return
    try:
        await destination.typing()
    except discord.NotFound:
        logger.warning("Channel not found when trying to send message.")
        return

    author = message.author
    member = self.bot.guild.get_member(author.id)
    if member:
        avatar_url = member.display_avatar.url
    else:
        avatar_url = author.display_avatar.url

    #  Extract content for blank/forwarded messages ---
    content = message.content
    if not content:
        # Try to extract from referenced message (replies)
        if hasattr(message, "reference") and message.reference is not None:
            try:
                ref = message.reference.resolved
                if ref and hasattr(ref, "content") and ref.content:
                    content = f"(Reply to: {ref.author}: {ref.content})"
            except Exception:
                pass
        # Try to extract from first embed's description
        if not content and message.embeds:
            first_embed = message.embeds[0]
            if hasattr(first_embed, "description") and first_embed.description:
                content = first_embed.description
        # Fallback: show something generic if still blank
        if not content:
            content = "[This is a forwarded message.]"

    embed = discord.Embed(description=content)
    if self.bot.config["show_timestamp"]:
        embed.timestamp = message.created_at

    system_avatar_url = "https://discordapp.com/assets/f78426a064bc9dd24847519259bc42af.png"

    if not note:
        if anonymous and from_mod and not isinstance(destination, discord.TextChannel):
            # Anonymously sending to the user.
            tag = self.bot.config["mod_tag"]
            if tag is None:
                tag = str(get_top_role(author, self.bot.config["use_hoisted_top_role"]))
            name = self.bot.config["anon_username"]
            if name is None:
                name = tag
            avatar_url = self.bot.config["anon_avatar_url"]
            if avatar_url is None:
                avatar_url = self.bot.get_guild_icon(guild=self.bot.guild, size=128)
            embed.set_author(
                name=name,
                icon_url=avatar_url,
                url=f"https://discordapp.com/channels/{self.bot.guild.id}#{message.id}",
            )
        else:
            # Normal message
            name = str(author)
            avatar_url = avatar_url
            embed.set_author(
                name=name,
                icon_url=avatar_url,
                url=f"https://discordapp.com/users/{author.id}#{message.id}",
            )
    else:
        # Notes are just replies with a different footer and color
        embed.set_author(
            name=str(author),
            icon_url=avatar_url,
            url=f"https://discordapp.com/users/{author.id}#{message.id}",
        )

    ext = [(a.url, a.filename, False) for a in message.attachments]

    images = []
    attachments = []
    for attachment in ext:
        if is_image_url(attachment[0]):
            images.append(attachment)
        else:
            attachments.append(attachment)

    image_urls = re.findall(
        r"http[s]?:\/\/(?:[a-zA-Z]|[0-9]|[$-_@.&+]|[!*(),]|(?:%[0-9a-fA-F][0-9a-fA-F]))+",
        message.content,
    )

    image_urls = [
        (is_image_url(url, convert_size=False), None, False)
        for url in image_urls
        if is_image_url(url, convert_size=False)
    ]
    images.extend(image_urls)

    def lottie_to_png(data):
        importer = l_importers.get("lottie")
        exporter = l_exporters.get("png")
        with io.BytesIO() as stream:
            stream.write(data)
            stream.seek(0)
            an = importer.process(stream)

        with io.BytesIO() as stream:
            exporter.process(an, stream)
            stream.seek(0)
            return stream.read()

    for i in message.stickers:
        if i.format in (
            discord.StickerFormatType.png,
            discord.StickerFormatType.apng,
            discord.StickerFormatType.gif,
        ):
            images.append(
                (f"https://media.discordapp.net/stickers/{i.id}.{i.format.file_extension}", i.name, True)
            )
        elif i.format == discord.StickerFormatType.lottie:
            # save the json lottie representation
            try:
                async with self.bot.session.get(i.url) as resp:
                    data = await resp.read()

                # convert to a png
                img_data = await self.bot.loop.run_in_executor(
                    None, functools.partial(lottie_to_png, data)
                )
                b64_data = base64.b64encode(img_data).decode()

                # upload to imgur
                async with self.bot.session.post(
                    "https://api.imgur.com/3/image",
                    headers={"Authorization": "Client-ID 50e96145ac5e085"},
                    data={"image": b64_data},
                ) as resp:
                    result = await resp.json()
                    url = result["data"]["link"]

            except Exception:
                traceback.print_exc()
                images.append((None, i.name, True))
            else:
                images.append((url, i.name, True))
        else:
            images.append((None, i.name, True))

    embedded_image = False

    prioritize_uploads = any(i[1] is not None for i in images)

    additional_images = []
    additional_count = 1

    for url, filename, is_sticker in images:
        if (
            not prioritize_uploads or ((url is None or is_image_url(url)) and filename)
        ) and not embedded_image:
            if url is not None:
                embed.set_image(url=url)
            if filename:
                if is_sticker:
                    if url is None:
                        description = f"{filename}: Unable to retrieve sticker image"
                    else:
                        description = f"[{filename}]({url})"
                    embed.add_field(name="Sticker", value=description)
                else:
                    embed.add_field(name="Image", value=f"[{filename}]({url})")
            embedded_image = True
        else:
            if note:
                color = self.bot.main_color
            elif from_mod:
                color = self.bot.mod_color
            else:
                color = self.bot.recipient_color

            img_embed = discord.Embed(color=color)

            if url is not None:
                img_embed.set_image(url=url)
                img_embed.url = url
            if filename is not None:
                img_embed.title = filename
            img_embed.set_footer(text=f"Additional Image Upload ({additional_count})")
            img_embed.timestamp = message.created_at
            additional_images.append(destination.send(embed=img_embed))
            additional_count += 1

    file_upload_count = 1

    for url, filename, _ in attachments:
        embed.add_field(name=f"File upload ({file_upload_count})", value=f"[{filename}]({url})")
        file_upload_count += 1

    if from_mod:
        embed.colour = self.bot.mod_color
        if note:
            embed.set_footer(text=f"{'Persistent' if persistent_note else ''} Internal Message")
        # Anonymous reply sent in thread channel
        elif anonymous and isinstance(destination, discord.TextChannel):
            embed.set_footer(text="Anonymous Reply")
        # Normal messages
        elif not anonymous:
            mod_tag = self.bot.config["mod_tag"]
            if mod_tag is None:
                mod_tag = str(get_top_role(message.author, self.bot.config["use_hoisted_top_role"]))
            embed.set_footer(text=mod_tag)  # Normal messages
        else:
            embed.set_footer(text=self.bot.config["anon_tag"])
    else:
        embed.set_footer(text=f"Message ID: {message.id}")
        embed.colour = self.bot.recipient_color

    if (from_mod or note) and not thread_creation:
        delete_message = not bool(message.attachments)
        if delete_message and destination == self.channel:
            try:
                await message.delete()
            except Exception as e:
                logger.warning("Cannot delete message: %s.", e)

    if (
        from_mod
        and self.bot.config["dm_disabled"] == DMDisabled.ALL_THREADS
        and destination != self.channel
    ):
        logger.info("Sending a message to %s when DM disabled is set.", self.recipient)

    try:
        await destination.typing()
    except discord.NotFound:
        logger.warning("Channel not found.")
        raise

    if not from_mod and not note:
        mentions = await self.get_notifications()
    else:
        mentions = None

    if plain:
        if from_mod and not isinstance(destination, discord.TextChannel):
            # Plain to user
            with warnings.catch_warnings():
                # Catch coroutines not awaited warning
                warnings.simplefilter("ignore")
                additional_images = []

            if embed.footer.text:
                plain_message = f"**{embed.footer.text} "
            else:
                plain_message = "**"
            plain_message += f"{embed.author.name}:** {embed.description}"
            files = []
            for i in message.attachments:
                files.append(await i.to_file())

            msg = await destination.send(plain_message, files=files)
        else:
            # Plain to mods
            embed.set_footer(text="[PLAIN] " + embed.footer.text)
            msg = await destination.send(mentions, embed=embed)

    else:
        msg = await destination.send(mentions, embed=embed)

    if additional_images:
        self.ready = False
        await asyncio.gather(*additional_images)
        self.ready = True

    return msg

def update_disabled_status(self):
    if self.current == self.first_page():
        # disable << button
        if self._buttons_map["<<"] is not None:
            self._buttons_map["<<"].disabled = True

        if self._buttons_map["<"] is not None:
            self._buttons_map["<"].disabled = True
    else:
        if self._buttons_map["<<"] is not None:
            self._buttons_map["<<"].disabled = False

        if self._buttons_map["<"] is not None:
            self._buttons_map["<"].disabled = False

    if self.current == self.last_page():
        # disable >> button
        if self._buttons_map[">>"] is not None:
            self._buttons_map[">>"].disabled = True

        if self._buttons_map[">"] is not None:
            self._buttons_map[">"].disabled = True
    else:
        if self._buttons_map[">>"] is not None:
            self._buttons_map[">>"].disabled = False

        if self._buttons_map[">"] is not None:
            self._buttons_map[">"].disabled = False

class EmbedPaginatorSession(PaginatorSession):
    def __init__(self, ctx: commands.Context, *embeds, **options):
        super().__init__(ctx, *embeds, **options)

        if len(self.pages) > 1:
            select_options = []
            create_select = True
            for i, embed in enumerate(self.pages):
                footer_text = f"Page {i + 1} of {len(self.pages)}"
                if embed.footer.text:
                    footer_text = footer_text + " • " + embed.footer.text

                if embed.footer.icon:
                    icon_url = embed.footer.icon.url if embed.footer.icon else None
                else:
                    icon_url = None
                embed.set_footer(text=footer_text, icon_url=icon_url)

                # select menu
                if embed.author.name:
                    title = embed.author.name[:30].strip()
                    if len(embed.author.name) > 30:
                        title += "..."
                else:
                    title = embed.title[:30].strip()
                    if len(embed.title) > 30:
                        title += "..."
                    if not title:
                        create_select = False

                if embed.description:
                    description = embed.description[:40].replace("*", "").replace("`", "").strip()
                    if len(embed.description) > 40:
                        description += "..."
                else:
                    description = ""
                select_options.append((title, description))

            if create_select:
                if len(set(x[0] for x in select_options)) != 1:  # must have unique authors
                    self.select_menu = PageSelect(self, select_options)

    def add_page(self, item: Embed) -> None:
        if isinstance(item, Embed):
            self.pages.append(item)
        else:
            raise TypeError("Page must be an Embed object.")

    async def _create_base(self, item: Embed, view: View) -> None:
        self.base = await self.destination.send(embed=item, view=view)

    def _show_page(self, page):
        return dict(embed=page)

class MessagePaginatorSession(PaginatorSession):
    def __init__(self, ctx: commands.Context, *messages, embed: Embed = None, **options):
        self.embed = embed
        self.footer_text = self.embed.footer.text if embed is not None else None
        super().__init__(ctx, *messages, **options)

    def add_page(self, item: str) -> None:
        if isinstance(item, str):
            self.pages.append(item)
        else:
            raise TypeError("Page must be a str object.")

    def _set_footer(self):
        if self.embed is not None:
            footer_text = f"Page {self.current+1} of {len(self.pages)}"
            if self.footer_text:
                footer_text = footer_text + " • " + self.footer_text

            if self.embed.footer.icon:
                icon_url = self.embed.footer.icon.url if self.embed.footer.icon else None
            else:
                icon_url = None

            self.embed.set_footer(text=footer_text, icon_url=icon_url)

    async def _create_base(self, item: str, view: View) -> None:
        self._set_footer()
        self.base = await self.ctx.send(content=item, embed=self.embed, view=view)

    def _show_page(self, page) -> typing.Dict:
        self._set_footer()
        return dict(content=page, embed=self.embed)

def _resolve_user(self, user_str):
    """Helper to resolve a user from mention, ID, or username."""
    import re

    if not user_str:
        return None
    if user_str.isdigit():
        return int(user_str)
    match = re.match(r"<@!?(\d+)>", user_str)
    if match:
        return int(match.group(1))
    return None

async def move(self, ctx, *, arguments):
    """
    Move a thread to another category.

    `category` may be a category ID, mention, or name.
    `options` is a string which takes in arguments on how to perform the move. Ex: "silently"
    """
    split_args = arguments.strip('"').split(" ")
    category = None

    # manually parse arguments, consumes as much of args as possible for category
    for i in range(len(split_args)):
        try:
            if i == 0:
                fmt = arguments
            else:
                fmt = " ".join(split_args[:-i])

            category = await SimilarCategoryConverter().convert(ctx, fmt)
        except commands.BadArgument:
            if i == len(split_args) - 1:
                # last one
                raise
            pass
        else:
            break

    if not category:
        raise commands.ChannelNotFound(arguments)

    options = " ".join(arguments.split(" ")[-i:])

    thread = ctx.thread
    silent = False

    if options:
        silent_words = ["silent", "silently"]
        silent = any(word in silent_words for word in options.split())

    await thread.channel.move(
        category=category, end=True, sync_permissions=True, reason=f"{ctx.author} moved this thread."
    )

    if self.bot.config["thread_move_notify"] and not silent:
        embed = discord.Embed(
            title=self.bot.config["thread_move_title"],
            description=self.bot.config["thread_move_response"],
            color=self.bot.main_color,
        )
        await thread.recipient.send(embed=embed)

    if self.bot.config["thread_move_notify_mods"]:
        mention = self.bot.config["mention"]
        if mention is not None:
            msg = f"{mention}, thread has been moved."
        else:
            msg = "Thread has been moved."
        await thread.channel.send(msg)

    sent_emoji, _ = await self.bot.retrieve_emoji()
    await self.bot.add_reaction(ctx.message, sent_emoji)

def parse_user_or_role(ctx, user_or_role):
    mention = None
    if user_or_role is None:
        mention = ctx.author.mention
    elif hasattr(user_or_role, "mention"):
        mention = user_or_role.mention
    elif user_or_role in {"here", "everyone", "@here", "@everyone"}:
        mention = "@" + user_or_role.lstrip("@")
    return mention

async def contact(
    self,
    ctx,
    users: commands.Greedy[
        Union[Literal["silent", "silently"], discord.Member, discord.User, discord.Role]
    ],
    *,
    category: SimilarCategoryConverter = None,
    manual_trigger=True,
):
    """
    Create a thread with a specified member.

    If `category` is specified, the thread
    will be created in that specified category.

    `category`, if specified, may be a category ID, mention, or name.
    `users` may be a user ID, mention, or name. If multiple users are specified, a group thread will start.
    A maximum of 5 users are allowed.
    `options` can be `silent` or `silently`.
    """
    silent = any(x in users for x in ("silent", "silently"))
    if silent:
        try:
            users.remove("silent")
        except ValueError:
            pass

        try:
            users.remove("silently")
        except ValueError:
            pass

    if isinstance(category, str):
        category = category.split()

        category = " ".join(category)
        if category:
            try:
                category = await SimilarCategoryConverter().convert(
                    ctx, category
                )  # attempt to find a category again
            except commands.BadArgument:
                category = None

        if isinstance(category, str):
            category = None

    errors = []
    for u in list(users):
        if isinstance(u, discord.Role):
            users += u.members
            users.remove(u)

    for u in list(users):
        exists = await self.bot.threads.find(recipient=u)
        if exists:
            errors.append(f"A thread for {u} already exists.")
            if exists.channel:
                errors[-1] += f" in {exists.channel.mention}"
            errors[-1] += "."
            users.remove(u)
        elif u.bot:
            errors.append(f"{u} is a bot, cannot add to thread.")
            users.remove(u)
        elif await self.bot.is_blocked(u):
            ref = f"{u.mention} is" if ctx.author != u else "You are"
            errors.append(f"{ref} currently blocked from contacting {self.bot.user.name}.")
            users.remove(u)

    if len(users) > 5:
        errors.append("Group conversations only support 5 users.")
        users = []

    if errors or not users:
        if not users:
            # no users left
            title = "Thread not created"
        else:
            title = None

        if manual_trigger:  # not react to contact
            embed = discord.Embed(title=title, color=self.bot.error_color, description="\n".join(errors))
            await ctx.send(embed=embed, delete_after=10)

        if not users:
            # end
            return

    creator = ctx.author if manual_trigger else users[0]

    thread = await self.bot.threads.create(
        recipient=users[0],
        creator=creator,
        category=category,
        manual_trigger=manual_trigger,
        # The minimum character check is enforced in ThreadManager.create
    )

    if thread.cancelled:
        return

    if self.bot.config["dm_disabled"] in (DMDisabled.NEW_THREADS, DMDisabled.ALL_THREADS):
        logger.info("Contacting user %s when Modmail DM is disabled.", users[0])

    if not silent and not self.bot.config.get("thread_contact_silently"):
        if creator.id == users[0].id:
            description = self.bot.config["thread_creation_self_contact_response"]
        else:
            description = self.bot.formatter.format(
                self.bot.config["thread_creation_contact_response"], creator=creator
            )

        em = discord.Embed(
            title=self.bot.config["thread_creation_contact_title"],
            description=description,
            color=self.bot.main_color,
        )
        if self.bot.config["show_timestamp"]:
            em.timestamp = discord.utils.utcnow()
        em.set_footer(
            text=f"{creator}", icon_url=creator.display_avatar.url if creator.display_avatar else None
        )

        for u in users:
            await u.send(embed=em)

    embed = discord.Embed(
        title="Created Thread",
        description=f"Thread started by {creator.mention} for {', '.join(u.mention for u in users)}.",
        color=self.bot.main_color,
    )
    await thread.wait_until_ready()

    if users[1:]:
        await thread.add_users(users[1:])

    await thread.channel.send(embed=embed)

    if manual_trigger:
        sent_emoji, _ = await self.bot.retrieve_emoji()
        await self.bot.add_reaction(ctx.message, sent_emoji)
        await asyncio.sleep(5)
        await ctx.message.delete()

async def blocked(self, ctx):
    """Retrieve a list of blocked users."""

    roles = []
    users = []
    now = ctx.message.created_at

    blocked_users = list(self.bot.blocked_users.items())
    for id_, reason in blocked_users:
        # parse "reason" and check if block is expired
        try:
            end_time, after = extract_block_timestamp(reason, id_)
        except ValueError:
            continue

        if end_time is not None:
            if after <= 0:
                # No longer blocked
                self.bot.blocked_users.pop(str(id_))
                logger.debug("No longer blocked, user %s.", id_)
                continue
        users.append((f"<@{id_}>", reason))

    blocked_roles = list(self.bot.blocked_roles.items())
    for id_, reason in blocked_roles:
        # parse "reason" and check if block is expired
        # etc "blah blah blah... until 2019-10-14T21:12:45.559948."
        try:
            end_time, after = extract_block_timestamp(reason, id_)
        except ValueError:
            continue

        if end_time is not None:
            if after <= 0:
                # No longer blocked
                self.bot.blocked_roles.pop(str(id_))
                logger.debug("No longer blocked, role %s.", id_)
                continue

        role = self.bot.guild.get_role(int(id_))
        if role:
            roles.append((role.mention, reason))

    user_embeds = [discord.Embed(title="Blocked Users", color=self.bot.main_color, description="")]

    if users:
        embed = user_embeds[0]

        for mention, reason in users:
            line = mention + f" - {reason or 'No Reason Provided'}\n"
            if len(embed.description) + len(line) > 2048:
                embed = discord.Embed(
                    title="Blocked Users",
                    color=self.bot.main_color,
                    description=line,
                )
                user_embeds.append(embed)
            else:
                embed.description += line
    else:
        user_embeds[0].description = "Currently there are no blocked users."

    if len(user_embeds) > 1:
        for n, em in enumerate(user_embeds):
            em.title = f"{em.title} [{n + 1}]"

    role_embeds = [discord.Embed(title="Blocked Roles", color=self.bot.main_color, description="")]

    if roles:
        embed = role_embeds[-1]

        for mention, reason in roles:
            line = mention + f" - {reason or 'No Reason Provided'}\n"
            if len(embed.description) + len(line) > 2048:
                role_embeds[-1].set_author()
                embed = discord.Embed(
                    title="Blocked Roles",
                    color=self.bot.main_color,
                    description=line,
                )
                role_embeds.append(embed)
            else:
                embed.description += line
    else:
        role_embeds[-1].description = "Currently there are no blocked roles."

    if len(role_embeds) > 1:
        for n, em in enumerate(role_embeds):
            em.title = f"{em.title} [{n + 1}]"

    session = EmbedPaginatorSession(ctx, *user_embeds, *role_embeds)

    await session.run()

async def blocked_whitelist(self, ctx, *, user: User = None):
    """
    Whitelist or un-whitelist a user from getting blocked.

    Useful for preventing users from getting blocked by account_age/guild_age restrictions.
    """
    if user is None:
        thread = ctx.thread
        if thread:
            user = thread.recipient
        else:
            return await ctx.send_help(ctx.command)

    mention = getattr(user, "mention", f"`{user.id}`")
    msg = ""

    if str(user.id) in self.bot.blocked_whitelisted_users:
        embed = discord.Embed(
            title="Success",
            description=f"{mention} is no longer whitelisted.",
            color=self.bot.main_color,
        )
        self.bot.blocked_whitelisted_users.remove(str(user.id))
        return await ctx.send(embed=embed)

    self.bot.blocked_whitelisted_users.append(str(user.id))

    if str(user.id) in self.bot.blocked_users:
        msg = self.bot.blocked_users.get(str(user.id)) or ""
        self.bot.blocked_users.pop(str(user.id))

    await self.bot.config.update()

    if msg.startswith("System Message: "):
        # If the user is blocked internally (for example: below minimum account age)
        # Show an extended message stating the original internal message
        reason = msg[16:].strip().rstrip(".")
        embed = discord.Embed(
            title="Success",
            description=f"{mention} was previously blocked internally for "
            f'"{reason}". {mention} is now whitelisted.',
            color=self.bot.main_color,
        )
    else:
        embed = discord.Embed(
            title="Success",
            color=self.bot.main_color,
            description=f"{mention} is now whitelisted.",
        )

    return await ctx.send(embed=embed)

async def snooze_auto_unsnooze_task(self):
    await self.bot.wait_until_ready()
    while True:
        now = datetime.utcnow()
        snoozed = await self.bot.api.logs.find({"snoozed": True}).to_list(None)
        for entry in snoozed:
            start = entry.get("snooze_start")
            snooze_for = entry.get("snooze_for")
            if not start:
                continue
            start_dt = datetime.fromisoformat(start)
            if snooze_for is not None:
                duration = int(snooze_for)
            else:
                max_snooze = self.bot.config.get("max_snooze_time")
                if max_snooze is None:
                    max_snooze = 604800
                duration = int(max_snooze)
            if (now - start_dt).total_seconds() > duration:
                # Auto-unsnooze
                thread = await self.bot.threads.find(recipient_id=int(entry["recipient"]["id"]))
                if thread and thread.snoozed:
                    await thread.restore_from_snooze()
        await asyncio.sleep(60)

