async def eval_(self, ctx, *, body: str):
    """Evaluates Python code."""

    logger.warning("Running eval command:\n%s", body)

    env = {
        "ctx": ctx,
        "bot": self.bot,
        "channel": ctx.channel,
        "author": ctx.author,
        "guild": ctx.guild,
        "message": ctx.message,
        "source": inspect.getsource,
        "discord": __import__("discord"),
    }

    env.update(globals())

    body = utils.cleanup_code(body)
    stdout = StringIO()

    to_compile = f'async def func():\n{indent(body, "  ")}'

    def paginate(text: str):
        """Simple generator that paginates text."""
        last = 0
        pages = []
        appd_index = curr = None
        for curr in range(0, len(text)):
            if curr % 1980 == 0:
                pages.append(text[last:curr])
                last = curr
                appd_index = curr
        if appd_index != len(text) - 1:
            pages.append(text[last:curr])
        return list(filter(lambda a: a != "", pages))

    try:
        exec(to_compile, env)  # pylint: disable=exec-used
    except Exception as exc:
        await ctx.send(f"```py\n{exc.__class__.__name__}: {exc}\n```")
        return await self.bot.add_reaction(ctx.message, "\u2049")

    func = env["func"]
    try:
        with redirect_stdout(stdout):
            ret = await func()
    except Exception:
        value = stdout.getvalue()
        await ctx.send(f"```py\n{value}{traceback.format_exc()}\n```")
        return await self.bot.add_reaction(ctx.message, "\u2049")

    else:
        value = stdout.getvalue()
        if ret is None:
            if value:
                try:
                    await ctx.send(f"```py\n{value}\n```")
                except Exception:
                    paginated_text = paginate(value)
                    for page in paginated_text:
                        if page == paginated_text[-1]:
                            await ctx.send(f"```py\n{page}\n```")
                            break
                        await ctx.send(f"```py\n{page}\n```")
        else:
            try:
                await ctx.send(f"```py\n{value}{ret}\n```")
            except Exception:
                paginated_text = paginate(f"{value}{ret}")
                for page in paginated_text:
                    if page == paginated_text[-1]:
                        await ctx.send(f"```py\n{page}\n```")
                        break
                    await ctx.send(f"```py\n{page}\n```")

    await self.bot.add_reaction(ctx.message, "\u2705")

