def is_allowed_origin(self, origin: str) -> bool:
    if origin in self.allow_origins:
        return True
    if origin == "null":
        return False
    if self.allow_origin_regex is not None and self.allow_origin_regex.fullmatch(origin):
        return True

    return self.allow_all_origins

def show_spinner(self, message: str, duration: float = 1.0):
    """Show spinner animation"""
    spinner_chars = "⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏"
    end_time = time.time() + duration

    print(
        f"{Colors.BOLD}{Colors.CYAN}{message}... {Colors.ENDC}", end="", flush=True
    )

    i = 0
    while time.time() < end_time:
        print(
            f"\r{Colors.BOLD}{Colors.CYAN}{message}... {Colors.YELLOW}{spinner_chars[i % len(spinner_chars)]}{Colors.ENDC}",
            end="",
            flush=True,
        )
        time.sleep(0.1)
        i += 1

    print(
        f"\r{Colors.BOLD}{Colors.CYAN}{message}... {Colors.OKGREEN}✓{Colors.ENDC}"
    )

def add_to_history(self, input_source: str, result: dict):
    """Add processing result to history"""
    entry = {
        "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
        "input_source": input_source,
        "status": result.get("status", "unknown"),
        "result": result,
    }
    self.processing_history.append(entry)

    def test_processes_workers_quit_unexpected(self):
        content = """
from locust import runners, events, User, task
import sys
runners.HEARTBEAT_INTERVAL = 0.1

@events.test_start.add_listener
def on_test_start(environment, **_kwargs):
    if isinstance(environment.runner, runners.WorkerRunner):
        sys.exit(42)

class AnyUser(User):
    @task
