def edit(self) -> t.Union[T_RESPONSE, str]:
    """
    Edit view method
    """
    next_url = None

    path: t.Union[str, list[str]] = request.args.getlist("path")
    if not path:
        return redirect(self.get_url(".index_view"))

    if len(path) > 1:
        next_url = self.get_url(".edit", path=path[1:])

    path = path[0]

    base_path, full_path, path = self._normalize_path(path)

    if not self.is_accessible_path(path) or not self.is_file_editable(path):
        flash(gettext("Permission denied."), "error")
        return redirect(self._get_dir_url(".index_view"))

    dir_url = self._get_dir_url(".index_view", op.dirname(path))
    next_url = next_url or dir_url

    form = self.edit_form()
    error = False

    if self.validate_form(form):
        form.process(request.form, content="")
        if form.validate():
            try:
                self.storage.write_file(  # type: ignore[union-attr]
                    full_path, request.form["content"]
                )
            except OSError:
                flash(
                    gettext("Error saving changes to %(name)s.", name=path), "error"
                )
                error = True
            else:
                self.on_edit_file(full_path, path)
                flash(
                    gettext("Changes to %(name)s saved successfully.", name=path),
                    "success",
                )
                return redirect(next_url)
    else:
        helpers.flash_errors(form, message="Failed to edit file. %(error)s")

        try:
            content = self.storage.read_file(full_path)  # type: ignore[union-attr]
        except OSError:
            flash(gettext("Error reading %(name)s.", name=path), "error")
            error = True
        except:  # noqa: E722
            flash(
                gettext("Unexpected error while reading from %(name)s", name=path),
                "error",
            )
            error = True
        else:
            try:
                content = content.decode("utf8")
            except UnicodeDecodeError:
                flash(gettext("Cannot edit %(name)s.", name=path), "error")
                error = True
            except:  # noqa: E722
                flash(
                    gettext(
                        "Unexpected error while reading from %(name)s", name=path
                    ),
                    "error",
                )
                error = True
            else:
                form.content.data = content  # type: ignore[attr-defined]

        if error:
            return redirect(next_url)

    if self.edit_modal and request.args.get("modal"):
        template = self.edit_modal_template
    else:
        template = self.edit_template

    return self.render(
        template,
        dir_url=dir_url,
        path=path,
        form=form,
        error=error,
        header_text=gettext("Editing %(path)s", path=path),
    )

def make_all(path: Path, jobs: int = multiprocessing.cpu_count()):
    """
    Build the binaries for a given test group.
    """
    if not path.exists():
        raise ValueError(f"given non-existent path {path}")

    print(f"[+] make -C {path} -j{jobs} all")
    try:
        subprocess.check_call(
            [
                "make",
                f"-j{jobs}",
                "ZIGCC=" + os.path.join(os.path.dirname(ziglang.__file__), "zig") + " cc",
                "all",
            ],
            cwd=str(path),
        )
    except subprocess.CalledProcessError:
        sys.exit(1)

def without_suffix(self):
    """Return a new path without the file suffix.  Readable alternative 
    for providing empty string to with_suffix.
    """
    return self.with_suffix('')

def test(
    obj: dict,
    fail_fast: bool,
    cov: bool,
    cov_fail_under: int,
    base_ref: str,
    workers: int,
    package_names: tuple,
):
    # Fail on incompatible configurations
    if cov_fail_under and not cov:
        raise click.UsageError(
            "You have to pass --cov in order to use --cov-fail-under"
        )

    if base_ref is not None and not base_ref:
        raise click.UsageError("Option '--base-ref' cannot be empty.")

    if not package_names and not base_ref:
        raise click.UsageError(
            "Either pass '--base-ref' or provide at least one package name."
        )

    console = obj["console"]
    repo_root = obj["repo_root"]
    debug: bool = obj["debug"]
    packages_to_test: set[Path] = set()
    all_packages = find_all_packages(repo_root)

    if package_names:
        changed_packages: set[Path] = {repo_root / Path(pn) for pn in package_names}
    else:
        # Get the files that changed from the base branch
        changed_files = get_changed_files(repo_root, base_ref)
        # Get the packages containing the changed files
        changed_packages = get_changed_packages(changed_files, all_packages)

    # Find the dependants of the changed packages
    # Skip dependants if we're checking coverage
    if cov:
        dependants = set()
    else:
        dependants = get_dependants_packages(changed_packages, all_packages)

    # Test the packages directly affected and their dependants
    packages_to_test = changed_packages | dependants

    # Test the packages using a process pool
    results = []
    with concurrent.futures.ProcessPoolExecutor(max_workers=int(workers)) as executor:
        future_to_package = {
            executor.submit(
                _run_tests,
                package_path,
                changed_packages,
                base_ref,
                cov,
                cov_fail_under,
            ): package_path
            for package_path in sorted(packages_to_test)
        }

        for future in concurrent.futures.as_completed(future_to_package):
            result = future.result()
            results.append(result)

            # Print results as they complete
            package: Path = result["package"]
            package_name = package.relative_to(repo_root)
            if result["status"] == ResultStatus.INSTALL_FAILED:
                console.print(f"❗ Unable to build package {package_name}")
                console.print(
                    _trim(debug, f"Error:\n{result['stderr']}"), style="warning"
                )
            elif result["status"] == ResultStatus.TESTS_PASSED:
                console.print(f"✅ {package_name} succeeded in {result['time']}")
            elif result["status"] == ResultStatus.UNSUPPORTED_PYTHON_VERSION:
                console.print(
                    f"⏭️ {package_name} skipped due to python version incompatibility"
                )
                console.print(
                    _trim(debug, f"Error:\n{result['stderr']}"), style="warning"
                )
            elif result["status"] == ResultStatus.NO_TESTS:
                console.print(f"⏭️ {package_name} skipped due to no tests")
                console.print(
                    _trim(debug, f"Error:\n{result['stderr']}"), style="warning"
                )
            else:
                console.print(f"❌ {package_name} failed")
                console.print(
                    _trim(debug, f"Error:\n{result['stderr']}"), style="error"
                )
                console.print(
                    _trim(debug, f"Output:\n{result['stdout']}"), style="info"
                )

    # Print summary
    failed = [
        r["package"].relative_to(repo_root)
        for r in results
        if r["status"] in (ResultStatus.TESTS_FAILED, ResultStatus.COVERAGE_FAILED)
    ]
    install_failed = [
        r["package"].relative_to(repo_root)
        for r in results
        if r["status"] == ResultStatus.INSTALL_FAILED
    ]
    skipped_no_tests = [
        r["package"].relative_to(repo_root)
        for r in results
        if r["status"] == ResultStatus.NO_TESTS
        and "package has no tests" in r["stderr"]
    ]
    skipped_pyversion_incompatible = [
        r["package"].relative_to(repo_root)
        for r in results
        if r["status"] == ResultStatus.UNSUPPORTED_PYTHON_VERSION
        and "Not compatible with Python" in r["stderr"]
    ]

    if skipped_pyversion_incompatible:
        console.print(
            f"\n{len(skipped_pyversion_incompatible)} packages were skipped due to Python version incompatibility:"
        )
        for p in skipped_pyversion_incompatible:
            print(p)
    if skipped_no_tests:
        console.print(
            f"\n{len(skipped_no_tests)} packages were skipped because they have no tests:"
        )
        for p in skipped_no_tests:
            print(p)

    if install_failed:
        # Do not fail the CI if there was an installation problem: many packages cannot
        # be installed in the runners, something we should either fix or ignore.
        console.print(f"\n{len(install_failed)} packages could not be installed:")
        for p in install_failed:
            print(p)

    if failed:
        console.print(f"\n{len(failed)} packages had test failures:")
        for p in failed:
            console.print(p)
        exit(1)
    else:
        console.print(
            f"\nTests passed for {len(results) - len(skipped_no_tests) - len(skipped_pyversion_incompatible)} packages.",
            style="green",
        )

class Settings:
    """
    A singleton class for DSPy configuration settings.
    Thread-safe global configuration.
    - 'configure' can be called by only one 'owner' thread (the first thread that calls it).
    - Other threads see the configured global values from 'main_thread_config'.
    - 'context' sets thread-local overrides. These overrides propagate to threads spawned
      inside that context block, when (and only when!) using a ParallelExecutor that copies overrides.

      1. Only one unique thread (which can be any thread!) can call dspy.configure.
      2. It affects a global state, visible to all. As a result, user threads work, but they shouldn't be
         mixed with concurrent changes to dspy.configure from the "main" thread.
         (TODO: In the future, add warnings: if there are near-in-time user-thread reads followed by .configure calls.)
      3. Any thread can use dspy.context. It propagates to child threads created with DSPy primitives: Parallel, asyncify, etc.
    """

    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

    @property
    def lock(self):
        return global_lock

    def __getattr__(self, name):
        overrides = thread_local_overrides.get()
        if name in overrides:
            return overrides[name]
        elif name in main_thread_config:
            return main_thread_config[name]
        else:
            raise AttributeError(f"'Settings' object has no attribute '{name}'")

    def __setattr__(self, name, value):
        if name in ("_instance",):
            super().__setattr__(name, value)
        else:
            self.configure(**{name: value})

    def __getitem__(self, key):
        return self.__getattr__(key)

    def __setitem__(self, key, value):
        self.__setattr__(key, value)

    def __contains__(self, key):
        overrides = thread_local_overrides.get()
        return key in overrides or key in main_thread_config

    def get(self, key, default=None):
        try:
            return self[key]
        except AttributeError:
            return default

    def copy(self):
        overrides = thread_local_overrides.get()
        return dotdict({**main_thread_config, **overrides})

    @property
    def config(self):
        return self.copy()

    def _ensure_configure_allowed(self):
        global main_thread_config, config_owner_thread_id, config_owner_async_task
        current_thread_id = threading.get_ident()

        if config_owner_thread_id is None:
            # First `configure` call assigns the owner thread id.
            config_owner_thread_id = current_thread_id

        if config_owner_thread_id != current_thread_id:
            # Disallow a second `configure` calls from other threads.
            raise RuntimeError("dspy.settings can only be changed by the thread that initially configured it.")

        # Async task doesn't allow a second `configure` call, must use dspy.context(...) instead.
        is_async_task = False
        try:
            if asyncio.current_task() is not None:
                is_async_task = True
        except RuntimeError:
            # This exception (e.g., "no current task") means we are not in an async loop/task,
            # or asyncio module itself is not fully functional in this specific sub-thread context.
            is_async_task = False

        if not is_async_task:
            return

        if config_owner_async_task is None:
            # First `configure` call assigns the owner async task.
            config_owner_async_task = asyncio.current_task()
            return

        # We are in an async task. Now check for IPython and allow calling `configure` from IPython.
        in_ipython = False
        try:
            from IPython import get_ipython

            # get_ipython is a global injected by IPython environments.
            # We check its existence and type to be more robust.
            in_ipython = get_ipython() is not None
        except Exception:
            # If `IPython` is not installed or `get_ipython` failed, we are not in an IPython environment.
            in_ipython = False

        if not in_ipython and config_owner_async_task != asyncio.current_task():
            raise RuntimeError(
                "dspy.settings.configure(...) can only be called from the same async task that called it first. Please "
                "use `dspy.context(...)` in other async tasks instead."
            )

    def configure(self, **kwargs):
        # If no exception is raised, the `configure` call is allowed.
        self._ensure_configure_allowed()

        # Update global config
        for k, v in kwargs.items():
            main_thread_config[k] = v

    @contextmanager
    def context(self, **kwargs):
        """
        Context manager for temporary configuration changes at the thread level.
        Does not affect global configuration. Changes only apply to the current thread.
        If threads are spawned inside this block using ParallelExecutor, they will inherit these overrides.
        """

        original_overrides = thread_local_overrides.get().copy()
        new_overrides = dotdict({**main_thread_config, **original_overrides, **kwargs})
        token = thread_local_overrides.set(new_overrides)

        try:
            yield
        finally:
            thread_local_overrides.reset(token)

    def __repr__(self):
        overrides = thread_local_overrides.get()
        combined_config = {**main_thread_config, **overrides}
        return repr(combined_config)

