def test_terminal_classes_has_status_code() -> None:
    terminals = set()
    for name in dir(web):
        obj = getattr(web, name)
        if isinstance(obj, type) and issubclass(obj, web.HTTPException):
            terminals.add(obj)

    dup = frozenset(terminals)
    for cls1 in dup:
        for cls2 in dup:
            if cls1 in cls2.__bases__:
                terminals.discard(cls1)

    for cls in terminals:
        assert cls.status_code is not None
    codes = collections.Counter(cls.status_code for cls in terminals)
    assert None not in codes
    assert 1 == codes.most_common(1)[0][1]

class EnsureOctetStream(Message):
    def __init__(self) -> None:
        super().__init__()
        self.set_default_type("application/octet-stream")

    def get_content_type(self) -> Any:
        """Re-implementation from Message

        Returns application/octet-stream in place of plain/text when
        value is wrong.

        The way this class is used guarantees that content-type will
        be present so simplify the checks wrt to the base implementation.
        """
        value = self.get("content-type").lower()

        # Based on the implementation of _splitparam in the standard library
        ctype, sep, _ = value.partition(";")
        if not sep:
            ctype = ctype.strip()
        if ctype.count("/") != 1:
            return self.get_default_type()
        return ctype

def should_close(self) -> bool:
    return bool(
        self._should_close
        or (self._payload is not None and not self._payload.is_eof())
        or self._upgraded
        or self._exception is not None
        or self._payload_parser is not None
        or self._buffer
        or self._tail
    )

def _job(j: list[int]) -> tuple[str, list[bytes]]:
    # Always start with a 256B headers chunk
    body = [b"0" * s for s in [256] + list(j)]
    job_title = f"{fm_size(sum(j))} / {len(j)}"
    return (job_title, body)

def chat_completions_create(self, model, messages, **kwargs):
    """Request chat completions from the Google AI API.

    Args:
    ----
        model (str): Identifies the specific provider/model to use.
        messages (list of dict): A list of message objects in chat history.
        kwargs (dict): Optional arguments for the Google AI API.

    Returns:
    -------
        The ChatCompletionResponse with the completion result.

    """

    # Set the temperature if provided, otherwise use the default
    temperature = kwargs.get("temperature", DEFAULT_TEMPERATURE)

    # Convert messages to Vertex AI format
    message_history = self.transformer.convert_request(messages)

    # Handle tools if provided
    tools = None
    if "tools" in kwargs:
        tools = [
            Tool(
                function_declarations=[
                    FunctionDeclaration(
                        name=tool["function"]["name"],
                        description=tool["function"].get("description", ""),
                        parameters={
                            "type": "object",
                            "properties": {
                                param_name: {
                                    "type": param_info.get("type", "string"),
                                    "description": param_info.get(
                                        "description", ""
                                    ),
                                    **(
                                        {"enum": param_info["enum"]}
                                        if "enum" in param_info
                                        else {}
                                    ),
                                }
                                for param_name, param_info in tool["function"][
                                    "parameters"
                                ]["properties"].items()
                            },
                            "required": tool["function"]["parameters"].get(
                                "required", []
                            ),
                        },
                    )
                    for tool in kwargs["tools"]
                ]
            )
        ]

    # Create the GenerativeModel
    model = GenerativeModel(
        model,
        generation_config=GenerationConfig(temperature=temperature),
        tools=tools,
    )

    if ENABLE_DEBUG_MESSAGES:
        print("Dumping the message_history")
        pprint.pprint(message_history)

    # Start chat and get response
    chat = model.start_chat(history=message_history[:-1])
    last_message = message_history[-1]

    # If the last message is a function response, send the Part object directly
    # Otherwise, send just the text content
    message_to_send = (
        Content(role="function", parts=[last_message])
        if isinstance(last_message, Part)
        else last_message.parts[0].text
    )
    # response = chat.send_message(message_to_send)
    response = chat.send_message(message_to_send)

    # Convert and return the response
    return self.transformer.convert_response(response)

