def test_detect_default_compilers(self):
    platform_default_compilers = {
        "Linux": "gcc",
        "Darwin": "apple-clang",
        "Windows": "msvc"
    }

    result = detect_defaults_settings()
    # result is a list of tuples (name, value) so converting it to dict
    result = dict(result)
    platform_compiler = platform_default_compilers.get(platform.system(), None)
    if platform_compiler is not None:
        self.assertEqual(result.get("compiler", None), platform_compiler)

def get_file_list(self, absolute_path=""):
    if not path_exists(absolute_path, self._store_folder):
        raise NotFoundException("")
    paths = relative_dirs(absolute_path)
    abs_paths = [os.path.join(absolute_path, relpath) for relpath in paths]
    return abs_paths

def delete_folder(self, path):
    """Delete folder from disk. Path already contains base dir"""
    if not path_exists(path, self._store_folder):
        raise NotFoundException("")
    rmdir(path)

def read_file(self, path, lock_file):
    with fasteners.InterProcessLock(lock_file):
        with open(path) as f:
            return f.read()

