    tools_paths = []
    tools_env_vars = dict()
    for mark in item.iter_markers():
        if mark.name.startswith("tool_"):
            raise Exception("Invalid decorator @pytest.mark.{}".format(mark.name))

    kwargs = [mark.kwargs for mark in item.iter_markers(name="tool")]
    if any(kwargs):
        raise Exception("Invalid decorator @pytest.mark Do not use kwargs: {}".format(kwargs))
    tools_params = [mark.args for mark in item.iter_markers(name="tool")]
    for tool_params in tools_params:
        if len(tool_params) == 1:
            tool_name = tool_params[0]
            tool_version = None
        elif len(tool_params) == 2:
            tool_name, tool_version = tool_params
        else:
            raise Exception("Invalid arguments for mark.tool: {}".format(tool_params))

        result = _get_tool(tool_name, tool_version)
        if result is True:
            version_msg = "Any" if tool_version is None else tool_version
            pytest.fail("Required '{}' tool version '{}' is not available".format(tool_name,
                                                                                  version_msg))
        if result is False:
            version_msg = "Any" if tool_version is None else tool_version
            pytest.skip("Required '{}' tool version '{}' is not available".format(tool_name,
                                                                                  version_msg))

        tool_path, tool_env = result
        if tool_path:
            tools_paths.append(tool_path)
        if tool_env:
            tools_env_vars.update(tool_env)
        # Fix random failures CI because of this: https://issues.jenkins.io/browse/JENKINS-9104
        if tool_name == "visual_studio":
            tools_env_vars['_MSPDBSRV_ENDPOINT_'] = str(uuid.uuid4())

    if tools_paths or tools_env_vars:
        item.old_environ = dict(os.environ)
        tools_env_vars['PATH'] = os.pathsep.join(tools_paths + [os.environ["PATH"]])
        os.environ.update(tools_env_vars)

def _use(
    self,
    tool_string: str,
    tool: CrewStructuredTool,
    calling: Union[ToolCalling, InstructorToolCalling],
) -> str:
    if self._check_tool_repeated_usage(calling=calling):  # type: ignore # _check_tool_repeated_usage of "ToolUsage" does not return a value (it only ever returns None)
        try:
            result = self._i18n.errors("task_repeated_usage").format(
                tool_names=self.tools_names
            )
            self._telemetry.tool_repeated_usage(
                llm=self.function_calling_llm,
                tool_name=tool.name,
                attempts=self._run_attempts,
            )
            result = self._format_result(result=result)  # type: ignore #  "_format_result" of "ToolUsage" does not return a value (it only ever returns None)
            return result  # type: ignore # Fix the return type of this function

        except Exception:
            if self.task:
                self.task.increment_tools_errors()

    if self.agent:
        event_data = {
            "agent_key": self.agent.key,
            "agent_role": self.agent.role,
            "tool_name": self.action.tool,
            "tool_args": self.action.tool_input,
            "tool_class": self.action.tool,
            "agent": self.agent,
        }

        if self.agent.fingerprint:
            event_data.update(self.agent.fingerprint)

        crewai_event_bus.emit(self,ToolUsageStartedEvent(**event_data))

    started_at = time.time()
    from_cache = False
    result = None  # type: ignore

    if self.tools_handler and self.tools_handler.cache:
        result = self.tools_handler.cache.read(
            tool=calling.tool_name, input=calling.arguments
        )  # type: ignore
        from_cache = result is not None

    available_tool = next(
        (
            available_tool
            for available_tool in self.tools
            if available_tool.name == tool.name
        ),
        None,
    )

    if result is None:
        try:
            if calling.tool_name in [
                "Delegate work to coworker",
                "Ask question to coworker",
            ]:
                coworker = (
                    calling.arguments.get("coworker") if calling.arguments else None
                )
                if self.task:
                    self.task.increment_delegations(coworker)

            if calling.arguments:
                try:
                    acceptable_args = tool.args_schema.model_json_schema()[
                        "properties"
                    ].keys()  # type: ignore
                    arguments = {
                        k: v
                        for k, v in calling.arguments.items()
                        if k in acceptable_args
                    }
                    # Add fingerprint metadata if available
                    arguments = self._add_fingerprint_metadata(arguments)
                    result = tool.invoke(input=arguments)
                except Exception:
                    arguments = calling.arguments
                    # Add fingerprint metadata if available
                    arguments = self._add_fingerprint_metadata(arguments)
                    result = tool.invoke(input=arguments)
            else:
                # Add fingerprint metadata even to empty arguments
                arguments = self._add_fingerprint_metadata({})
                result = tool.invoke(input=arguments)
        except Exception as e:
            self.on_tool_error(tool=tool, tool_calling=calling, e=e)
            self._run_attempts += 1
            if self._run_attempts > self._max_parsing_attempts:
                self._telemetry.tool_usage_error(llm=self.function_calling_llm)
                error_message = self._i18n.errors("tool_usage_exception").format(
                    error=e, tool=tool.name, tool_inputs=tool.description
                )
                error = ToolUsageErrorException(
                    f"\n{error_message}.\nMoving on then. {self._i18n.slice('format').format(tool_names=self.tools_names)}"
                ).message
                if self.task:
                    self.task.increment_tools_errors()
                if self.agent and self.agent.verbose:
                    self._printer.print(
                        content=f"\n\n{error_message}\n", color="red"
                    )
                return error  # type: ignore # No return value expected

            if self.task:
                self.task.increment_tools_errors()
            return self.use(calling=calling, tool_string=tool_string)  # type: ignore # No return value expected

        if self.tools_handler:
            should_cache = True
            if (
                hasattr(available_tool, "cache_function")
                and available_tool.cache_function  # type: ignore # Item "None" of "Any | None" has no attribute "cache_function"
            ):
                should_cache = available_tool.cache_function(  # type: ignore # Item "None" of "Any | None" has no attribute "cache_function"
                    calling.arguments, result
                )

            self.tools_handler.on_tool_use(
                calling=calling, output=result, should_cache=should_cache
            )
    self._telemetry.tool_usage(
        llm=self.function_calling_llm,
        tool_name=tool.name,
        attempts=self._run_attempts,
    )
    result = self._format_result(result=result)  # type: ignore # "_format_result" of "ToolUsage" does not return a value (it only ever returns None)
    data = {
        "result": result,
        "tool_name": tool.name,
        "tool_args": calling.arguments,
    }

    self.on_tool_use_finished(
        tool=tool,
        tool_calling=calling,
        from_cache=from_cache,
        started_at=started_at,
        result=result,
    )

    if (
        hasattr(available_tool, "result_as_answer")
        and available_tool.result_as_answer  # type: ignore # Item "None" of "Any | None" has no attribute "cache_function"
    ):
        result_as_answer = available_tool.result_as_answer  # type: ignore # Item "None" of "Any | None" has no attribute "result_as_answer"
        data["result_as_answer"] = result_as_answer  # type: ignore

    if self.agent and hasattr(self.agent, "tools_results"):
        self.agent.tools_results.append(data)

    return result

def _tool_calling(
    self, tool_string: str
) -> Union[ToolCalling, InstructorToolCalling, ToolUsageErrorException]:
    try:
        try:
            return self._original_tool_calling(tool_string, raise_error=True)
        except Exception:
            if self.function_calling_llm:
                return self._function_calling(tool_string)
            else:
                return self._original_tool_calling(tool_string)
    except Exception as e:
        self._run_attempts += 1
        if self._run_attempts > self._max_parsing_attempts:
            self._telemetry.tool_usage_error(llm=self.function_calling_llm)
            if self.task:
                self.task.increment_tools_errors()
            if self.agent and self.agent.verbose:
                self._printer.print(content=f"\n\n{e}\n", color="red")
            return ToolUsageErrorException(  # type: ignore # Incompatible return value type (got "ToolUsageErrorException", expected "ToolCalling | InstructorToolCalling")
                f"{self._i18n.errors('tool_usage_error').format(error=e)}\nMoving on then. {self._i18n.slice('format').format(tool_names=self.tools_names)}"
            )
        return self._tool_calling(tool_string)

def _get_project_attribute(
    pyproject_path: str, keys: List[str], require: bool
) -> Any | None:
    """Get an attribute from the pyproject.toml file."""
    attribute = None

    try:
        with open(pyproject_path, "r") as f:
            pyproject_content = parse_toml(f.read())

        dependencies = (
            _get_nested_value(pyproject_content, ["project", "dependencies"]) or []
        )
        if not any(True for dep in dependencies if "crewai" in dep):
            raise Exception("crewai is not in the dependencies.")

        attribute = _get_nested_value(pyproject_content, keys)
    except FileNotFoundError:
        print(f"Error: {pyproject_path} not found.")
    except KeyError:
        print(f"Error: {pyproject_path} is not a valid pyproject.toml file.")
    except tomllib.TOMLDecodeError if sys.version_info >= (3, 11) else Exception as e:  # type: ignore
        print(
            f"Error: {pyproject_path} is not a valid TOML file."
            if sys.version_info >= (3, 11)
            else f"Error reading the pyproject.toml file: {e}"
        )
    except Exception as e:
        print(f"Error reading the pyproject.toml file: {e}")

    if require and not attribute:
        console.print(
            f"Unable to read '{'.'.join(keys)}' in the pyproject.toml file. Please verify that the file exists and contains the specified attribute.",
            style="bold red",
        )
        raise SystemExit

    return attribute

def get_crew_instance(module_attr) -> Crew | None:
    if (
        callable(module_attr)
        and hasattr(module_attr, "is_crew_class")
        and module_attr.is_crew_class
    ):
        return module_attr().crew()
    if (ismethod(module_attr) or isfunction(module_attr)) and get_type_hints(
        module_attr
    ).get("return") is Crew:
        return module_attr()
    elif isinstance(module_attr, Crew):
        return module_attr
    else:
        return None

